 const [history,setHistory]=useState<FunnelGraph[]>([]),[future,setFuture]=useState<FunnelGraph[]>([]);const ideaAttemptRef=useRef<{fingerprint:string;requestId:string}|null>(null),ideaSubmittingRef=useRef(false);const inspectorRef=useRef<HTMLElement|null>(null),nodeOpenerRef=useRef<HTMLElement|null>(null);const path=`/api/products/${encodeURIComponent(product.id)}/funnel-builder`,spent=unlimited?0:cost,dirty=!!saved&&draftValue(saved)!==draftValue(draft),selectedNode=draft.graph.nodes.find(node=>node.id===selected),hasMap=draft.graph.nodes.length>0;
 const strategyStale=!!draft.strategy&&JSON.stringify(draft.brief)!==JSON.stringify(draft.strategyBrief);
 useEffect(()=>{let current=true;void requestWorkspace(path).then(({workspace})=>{if(current){setSaved(workspace);setDraft(workspace);setInterview(!workspace.updatedAt||!workspace.graph.nodes.length);setSelected(window.matchMedia('(min-width:901px)').matches?(workspace.graph.nodes.find(node=>node.type==='tofu')?.id||workspace.graph.nodes[0]?.id||null):null);setError('');}}).catch(reason=>{if(current)setError(reason.message);}).finally(()=>{if(current)setBusy('');});return()=>{current=false;};},[path,attempt]);
 useEffect(()=>{onDirtyChange?.(dirty);return()=>onDirtyChange?.(false);},[dirty,onDirtyChange]);useEffect(()=>{onBusyChange?.(!!busy);return()=>onBusyChange?.(false);},[busy,onBusyChange]);
 useEffect(()=>{const guard=(event:BeforeUnloadEvent)=>{if(dirty||busy){event.preventDefault();event.returnValue='';}};window.addEventListener('beforeunload',guard);return()=>window.removeEventListener('beforeunload',guard);},[dirty,busy]);
 function selectNode(id:string,reveal=true,opener?:HTMLElement){setSelected(id);if(opener)nodeOpenerRef.current=opener;if(reveal)requestAnimationFrame(()=>{const panel=inspectorRef.current;if(panel){const rect=panel.getBoundingClientRect();if(rect.top<80||rect.top>window.innerHeight-160)panel.scrollIntoView({block:'start',behavior:'instant'});panel.focus({preventScroll:true});}});}
 function closeDetails(){const opener=nodeOpenerRef.current?.isConnected?nodeOpenerRef.current:document.querySelector<HTMLElement>('.fj-node[aria-pressed=true],.fb-map-node-title[aria-pressed=true]');setSelected(null);requestAnimationFrame(()=>opener?.focus());}
 function accept(workspace:FunnelWorkspace){setSaved(workspace);setDraft(workspace);setHistory([]);setFuture([]);}
 async function persist(snapshot:FunnelWorkspace){const value={brief:snapshot.brief,graph:snapshot.graph,strategy:normalizedStrategy(snapshot.strategy),expectedUpdatedAt:snapshot.updatedAt},parsed=funnelSaveSchema.safeParse(value);if(!parsed.success)throw new Error(parsed.error.issues[0]?.message||'Complete the highlighted strategy fields before saving.');const {workspace}=await requestWorkspace(path,'PATCH',parsed.data);accept(workspace);return workspace;}
 async function save(){if(busy||!saved)return false;setBusy('save');setError('');setNotice('');try{await persist(draft);setNotice('Strategy saved privately. Your public pages and campaigns are unchanged.');return true;}catch(reason){setError((reason as Error).message);return false;}finally{setBusy('');}}
 useRegisterEditorSave({label:'Visual funnel strategy',dirty,busy:!!busy,save,priority:20,discard:()=>{if(saved)accept(saved);setError('');}});
 function remember(){setHistory(values=>[...values,draft.graph].slice(-40));setFuture([]);}
