 async function moreIdeas(){
  if(busy||ideaSubmittingRef.current||!saved||!aiReady||!ideaRequest)return;
  ideaSubmittingRef.current=true;const request=ideaRequest;setBusy('ideas');setError('');setNotice('');
  try{
   const base=dirty?await persist(draft):saved;
   const fingerprint=JSON.stringify({updatedAt:base.updatedAt,stage:request.stage,focus:request.focus.trim()});
   if(ideaAttemptRef.current?.fingerprint!==fingerprint)ideaAttemptRef.current={fingerprint,requestId:crypto.randomUUID()};
   const {workspace,spent:used}=await requestWorkspace(path+'/generate','POST',{expectedUpdatedAt:base.updatedAt,requestId:ideaAttemptRef.current.requestId,maxCredits:spent,mode:'ideas',stage:request.stage,focus:request.focus.trim()});
   ideaAttemptRef.current=null;accept(workspace);setIdeaToReveal(workspace.strategy?.stages.find(stage=>stage.id===request.stage)?.ideas[base.strategy?.stages.find(stage=>stage.id===request.stage)?.ideas.length||0]?.id||null);setIdeaRequest(null);setSelected(workspace.graph.nodes.find(node=>node.type===request.stage)?.id||null);
   setNotice(`3 new ${journeyStages[request.stage].label.toLowerCase()} ideas added. ${used||0} credits used. Your previous ideas, map and schedule are kept.`);onUpdate();
  }catch(reason){if(reason instanceof FunnelResponseError&&!(reason.status===409&&/still running/i.test(reason.message)))ideaAttemptRef.current=null;setError((reason as Error).message);}finally{ideaSubmittingRef.current=false;setBusy('');}
 }
 const loadCalendar=useCallback(async(signal?:AbortSignal)=>{try{const now=Date.now(),response=await fetch(`/api/calendar?startAt=${now-86400000}&endAt=${now+90*86400000}`,{cache:'no-store',signal}),data=await response.json() as CalendarWorkspace&{error?:string};if(!response.ok)throw new Error(data.error||'Schedule could not be loaded.');setCalendar({accounts:data.accounts,truncated:data.truncated,events:data.events.filter((event:CalendarEvent)=>event.productId===product.id&&event.source==='funnel-builder'&&event.status==='planned'&&event.endAt>now).sort((a:CalendarEvent,b:CalendarEvent)=>a.startAt-b.startAt)});setCalendarError('');}catch(reason){if(!signal?.aborted)setCalendarError((reason as Error).message);}},[product.id]);
 useEffect(()=>{const controller=new AbortController();void Promise.resolve().then(()=>loadCalendar(controller.signal));return()=>controller.abort();},[loadCalendar]);
 async function openSchedule(node:FunnelNode,idea?:FunnelIdea){if(busy)return;if(dirty||!saved?.updatedAt){if(!await save())return;}setSchedule({node,idea});}
 async function copy(text:string){try{await navigator.clipboard.writeText(text);setNotice('Copied to clipboard.');}catch{setError('Copy is unavailable. Select the outline text and copy it.');}}
